function machoArchs(h: Uint8Array): string[] {
  if (h.length < 8) return [];
  const v = new DataView(h.buffer, h.byteOffset, h.byteLength);
  const cpu = (t: number) =>
    ({ 12: 'armv7', 0x0100000c: 'arm64', 0x0200000c: 'arm64_32', 7: 'i386', 0x01000007: 'x86_64' } as Record<number, string>)[t] ?? `cpu${t}`;
  const be = v.getUint32(0);
  if (be === 0xcafebabe || be === 0xcafebabf) {
    const n = Math.min(v.getUint32(4), 8);
    const size = be === 0xcafebabf ? 32 : 20;
    const out: string[] = [];
    for (let i = 0; i < n && 8 + i * size + 4 <= h.length; i++) out.push(cpu(v.getInt32(8 + i * size) >>> 0));
    return out;
  }
  const le = v.getUint32(0, true);
  if (le === 0xfeedface || le === 0xfeedfacf) return [cpu(v.getInt32(4, true) >>> 0)];
  return [];
}
